// JavaScript has NO built-in heap — say so, then either hand-roll one or
// state that you are assuming a MinHeap class. Interviewers accept both.

class MinHeap {
  constructor(key = (x) => x) { this.a = []; this.key = key; }
  size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(v) {
    this.a.push(v);
    let i = this.a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.key(this.a[p]) <= this.key(this.a[i])) break;
      [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
      i = p;
    }
  }
  pop() {
    const top = this.a[0], last = this.a.pop();
    if (this.a.length) {
      this.a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < this.a.length && this.key(this.a[l]) < this.key(this.a[m])) m = l;
        if (r < this.a.length && this.key(this.a[r]) < this.key(this.a[m])) m = r;
        if (m === i) break;
        [this.a[m], this.a[i]] = [this.a[i], this.a[m]];
        i = m;
      }
    }
    return top;
  }
}

// Max-heap: negate the key.
const maxHeap = new MinHeap((x) => -x);

