def kClosest(points, k):
    heap = []
    for x, y in points:
        dist = x*x + y*y  # no need for sqrt
        heapq.heappush(heap, (-dist, x, y))  # max-heap by negating
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

