def leastInterval(tasks, n):
    count = list(Counter(tasks).values())
    heap = [-c for c in count]
    heapq.heapify(heap)
    time = 0
    cooldown = deque()  # (remaining_count, available_time)

    while heap or cooldown:
        time += 1
        if heap:
            cnt = heapq.heappop(heap) + 1  # process one
            if cnt: cooldown.append((cnt, time + n))
        if cooldown and cooldown[0][1] == time:
            heapq.heappush(heap, cooldown.popleft()[0])

    return time

